insert into dimensions (code, name, description, default_weight, display_order) values
  ('ANI', 'Bien-être animal (non-humain)', 'Élevage, cuirs, laine, duvet, fourrure, tests, abattage et transport des animaux non-humains.', 0.15, 4),
  ('ENV', 'Environnement', 'Climat, émissions, matières, biodiversité.', 0.15, 1),
  ('GEO', 'Géopolitique & Prises de position', 'Lobbying, financement politique, positionnements (ex: retrait de Russie).', 0.1, 5),
  ('GOV', 'Gouvernance', 'Indépendance du conseil, sanctions réglementaires, contrôle.', 0.1, 7),
  ('INV', 'Investissements & Finance éthique', 'Où la société place et finance son argent : finance durable, désinvestissement fossile, relations bancaires, participations dans des secteurs controversés.', 0.1, 8),
  ('LAB', 'Travail & Rémunération', 'Conditions de travail, équité salariale, dialogue social (bien-être des animaux humains, en interne).', 0.15, 2),
  ('PLA', 'Plastique', 'Pollution plastique (Break Free From Plastic), emballages recyclés/réutilisables, réduction du plastique vierge.', 0.125, 9),
  ('SUP', 'Chaîne d''appro & Droits humains', 'Devoir de vigilance, transparence fournisseurs, droits humains (bien-être des animaux humains, en amont).', 0.15, 3),
  ('TAX', 'Fiscalité', 'Transparence pays-par-pays, présence en juridictions à faible imposition.', 0.15, 6),
  ('WAT', 'Eau', 'Empreinte eau : note CDP Water, intensité de prélèvement, stress hydrique et controverses.', 0.125, 10)
