insert into source_tier_config (tier, evidence_weight, max_confidence, can_penalize_alone, min_score_floor_alone, notes) values
  ('audited_ngo', 0.8, 0.85, true, 0, 'Index/ONG audité (FTI, KnowTheChain, BBFAW, Textile Exchange). Très fiable mais non régalien.'),
